  { "name": "cnt",        "wave": "=.=.=.=.=.=.", "data": ["0","1","2","0","1","2"] },
  { "name": "a (posedge, cnt==0)", "wave": "1.0...1.0..." },
  { "name": "b (negedge, cnt==1)", "wave": "0..1.0...1.0" },
  { "name": "out = a|b",  "wave": "1.01.01.01.0" }
],
